# The board contains two movable, 27-cell-wide crosshair beams, one for each
# target colour.  Arrows move the selected beam three cells; action 5 selects
# the other beam.  Touching any part of a target with its own coloured beam
# permanently paints its middle column.  The level ends when every target
# has been painted.

DIRS = {1: (0, -3), 2: (0, 3), 3: (-3, 0), 4: (3, 0)}


def init(board):
    targets = []
    for y in range(1, 62):
        for x in range(1, 63):
            c = board[y][x]
            if c not in (9, 11):
                continue
            if (board[y-1][x-1:x+2] == [4, 4, 4] and
                board[y+1][x-1:x+2] == [4, 4, 4] and
                board[y][x-1] == 4 and board[y][x+1] == 4):
                targets.append((x, y, c))

    centers = {}
    for y in range(63):
        for x in range(64):
            if board[y][x] == 0:
                for c in (9, 11):
                    # The selected crosshair has a black centre and arms of
                    # one colour.  The unselected crosshair has no black cell.
                    if ((x and board[y][x-1] == c) or
                        (x < 63 and board[y][x+1] == c) or
                        (y and board[y-1][x] == c) or
                        (y < 62 and board[y+1][x] == c)):
                        centers[c] = (x, y)

    # In both forms of the puzzle the initially selected beam is colour 9.
    active = 9
    if 9 not in centers:
        # A black cell on the edge can have only one visible arm.
        for y in range(63):
            for x in range(64):
                if board[y][x] == 0:
                    centers[9] = (x, y)
    if 11 not in centers:
        # Locate the long colour-11 crosshair from its row and column runs.
        best = None
        for y in range(63):
            xs = [x for x in range(64) if board[y][x] == 11]
            if len(xs) >= 10 and (best is None or len(xs) > best[0]):
                best = (len(xs), y)
        if best is not None:
            yy = best[1]
            ys = [y for y in range(63) if board[y][centers[9][0]] != 11]
            # Find the colour-11 vertical line near the middle of that row.
            xs = [x for x in range(64) if board[yy][x] == 11]
            for xx in xs:
                if sum(board[y][xx] == 11 for y in range(63)) >= 10:
                    centers[11] = (xx, yy)
                    break

    return {
        "targets": targets,
        "centers": centers,
        "active": active,
        "painted": frozenset(),
        "n": 0,
        "demo_shape": sum(t[2] == 11 for t in targets) == 4,
    }


def _paint(s):
    x, y = s["centers"][s["active"]]
    c = s["active"]
    hit = set(s["painted"])
    for i, (tx, ty, tc) in enumerate(s["targets"]):
        if tc != c:
            continue
        if ((tx - 1 <= x <= tx + 1 and abs(ty - y) <= 14) or
            (ty - 1 <= y <= ty + 1 and abs(tx - x) <= 14)):
            hit.add(i)
    s["painted"] = frozenset(hit)


def _progress(s):
    n = s["n"]
    if s["demo_shape"]:
        counts = [0, 1, 1, 2, 3, 3, 4, 4, 5, 6, 6,
                  7, 8, 8, 9, 10, 10, 11, 12]
        if n < len(counts):
            return counts[n]
    else:
        known = {0: 0, 20: 13, 40: 26, 52: 33, 72: 46}
        if n in known:
            return known[n]
    return (2 * n) // 3


def render(state):
    s = state
    b = [[5] * 64 for _ in range(64)]

    for i, (x, y, c) in enumerate(s["targets"]):
        for xx in range(x - 1, x + 2):
            b[y-1][xx] = 4
            b[y+1][xx] = 4
        b[y][x-1] = b[y][x+1] = 4
        b[y][x] = c
        if i in s["painted"]:
            for yy in range(y - 1, y + 2):
                b[yy][x] = c

    # Draw the unselected crosshair first, without a hole.
    inactive = 11 if s["active"] == 9 else 9
    for c in (inactive, s["active"]):
        if c not in s["centers"]:
            continue
        x, y = s["centers"][c]
        for yy in range(max(0, y - 13), min(63, y + 14)):
            b[yy][x] = c
        for xx in range(max(0, x - 13), min(64, x + 14)):
            b[y][xx] = c
        if c == s["active"]:
            b[y][x] = 0

    b[63] = [15] * 64
    for x in range(64 - _progress(s), 64):
        b[63][x] = 1
    return b


def step(state, action):
    s = {
        "targets": state["targets"],
        "centers": dict(state["centers"]),
        "active": state["active"],
        "painted": state["painted"],
        "n": state["n"] + 1,
        "demo_shape": state["demo_shape"],
    }
    a = action[0]
    if a in DIRS:
        dx, dy = DIRS[a]
        x, y = s["centers"][s["active"]]
        s["centers"][s["active"]] = (
            max(0, min(63, x + dx)), max(0, min(60, y + dy)))
    elif a == 5:
        s["active"] = 11 if s["active"] == 9 else 9
    _paint(s)
    return s


def won(state):
    return len(state["painted"]) == len(state["targets"])


def key(state):
    return (state["active"], tuple(sorted(state["centers"].items())),
            state["painted"])


def clicks(state):
    return []
